import IconifyIcon from "@/components/wrappers/IconifyIcon";
import useCheckIn from "@/hooks/useCheckIn";
import { useState } from "react";
import { Button } from "react-bootstrap";
import { Link, useLocation } from "react-router-dom";
import AgreementPage from "./pages/AgreementPage";
import DocumentsPage from "./pages/DocumentsPage";
import InspectionPage from "./pages/InspectionPage";
import KeyHandoverPage from "./pages/KeyHandoverPage";
import OverviewPage from "./pages/OverviewPage";
import PropertyDetailsPage from "./pages/PropertyDetailsPage";
import RepairApprovalPage from "./pages/RepairApprovalPage";
import TenantDetailsPage from "./pages/TenantDetailsPage";
import UtilityReadingsPage from "./pages/UtilityReadingsPage";
import InspectionFormIcon from "@/assets/icons/InspectionFormIcon";
import AgreementIcon from "./edit-detail-page/icons/Aggrement.png";
import DocumentsIcon from "./edit-detail-page/icons/Documents.png";
import KeyhandlorIcon from "./edit-detail-page/icons/Keyhandlor.png";

const pageText = "#526b89";
const darkButton = "#30375f";

// Until a record loads from the API (or while it's unreachable), the
// summary below shows this demo data so the UI keeps working.

const fallbackDetailItems = [
  { label: "Tenant", value: "Bilal Ahmed" },
  { label: "Property", value: "A-401, Ocean View" },
  { label: "Unit No", value: "A-401" },
  { label: "Check-in Date", value: "29 May 2025" },
  { label: "Assigned To", value: "Ramesh Kumar" },
  { label: "Check-in Status", value: "Completeed" },
  { label: "Mobile No.", value: "+911 1234567890" },
  { label: "Tenant Type", value: "Individual" },
];

const fallbackStatus = "Completed";
const fallbackCode = "CL-12345665";


const buildDetailItems = (item) => {
  if (!item) return fallbackDetailItems;

  return [
    { label: "Tenant", value: item.tenantName || "–" },
    { label: "Property", value: item.buildingName || item.propertyDetails?.propertyName || "–" },
    { label: "Unit No", value: item.flatUnitNumber || "–" },
    { label: "Check-in Date", value: item.checkInDate || "–" },
    { label: "Assigned To", value: item.assignedEmployee?.name || "–" },
    { label: "Check-in Status", value: item.checkInStatus || "–" },
    { label: "Mobile No.", value: item.tenantMobileNumber || "–" },
    { label: "Tenant Type", value: item.tenantType || "–" },
  ];
};

const tabs = [
  {
    key: "overview",
    label: "Overview",
    iconSvg: (
      <img width={20} height={20} alt="Overview" style={{display:"block"}} src="data:image/png;base64," />
    ),
    component: OverviewPage,
  },
  {
    key: "tenantDetails",
    label: "Tenant Details",
    iconSvg: (
      <img width={20} height={20} alt="Tenant Details" style={{display:"block"}} src="data:image/png;base64," />
    ),
    component: TenantDetailsPage,
  },
  {
    key: "propertyDetails",
    label: "Property Details",
    iconSvg: (
      <img width={20} height={20} alt="Property Details" style={{display:"block"}} src="data:image/png;base64," />
    ),
    component: PropertyDetailsPage,
  },
  {
    key: "inspection",
    label: "Inspection",
     iconSvg: (
      <InspectionFormIcon />

    ),
    component: InspectionPage,
  },
  {
    key: "repairApproval",
    label: "Repair & Approval",
      iconSvg: (
        <img width={20} height={20} alt="Repair &amp; Approval" style={{display:"block"}} src={"data:image/png;base64,"} />


    ),
    component: RepairApprovalPage,
  },
  {
    key: "utilityReadings",
    label: "Utility Readings",
      iconSvg: (
        <img width={20} height={20} alt="Utility Readings" style={{display:"block"}} src={"data:image/png;base64,"} />



    ),
    component: UtilityReadingsPage,
  },
  {
    key: "agreement",
    label: "Agreement",
    iconSvg: (
      <img width={20} height={20} alt="Agreement" style={{display:"block"}} src={AgreementIcon} />
    ),
    component: AgreementPage,
  },
  {
    key: "keyHandover",
    label: "Key Handover",
    iconSvg: (
      <img width={20} height={20} alt="Key Handover" style={{display:"block"}} src={KeyhandlorIcon} />
    ),
    component: KeyHandoverPage,
  },
  {
    key: "documents",
    label: "Documents",
    iconSvg: (
      <img width={20} height={20} alt="Documents" style={{display:"block"}} src={DocumentsIcon} />
    ),
    component: DocumentsPage,
  },
];

const editSectionByTab = {
  overview: 'check-in-information',
  tenantDetails: 'tenant-details',
  propertyDetails: 'property-details',
  inspection: 'property-inspection',
  repairApproval: 'repair-approval',
  utilityReadings: 'utility-meter-readings',
  agreement: 'agreement-details',
  keyHandover: 'key-handover',
  documents: 'documents-upload',
};

const shellStyle = {
  background: "#f6f7fb",
  margin: "0 -48px",
  minHeight: "calc(100vh - 80px)",
  paddingTop: 10,
};

const topBarStyle = {
  background: "#fff",
  borderBottom: "1px solid #eef1f5",
  padding: "28px 56px 12px",
};

const cardStyle = {
  background: "#fff",
  borderRadius: 8,
  boxShadow: "0 8px 26px rgba(15, 23, 42, 0.08)",
};

const outlineButtonStyle = {
  border: "1px solid #b8b6ff",
  borderRadius: 5,
  color: darkButton,
  height: 40,
  minWidth: 100,
};

const primaryButtonStyle = {
  background: darkButton,
  borderColor: darkButton,
  borderRadius: 5,
  height: 40,
  minWidth: 140,
};

const CheckInDetailsPage = () => {
  const location = useLocation();
  const params = new URLSearchParams(location.search);
  const id = params.get("id");
  const tabParam = params.get("tab");
  const initialTab = tabs.find((t) => t.key === tabParam)?.key ?? tabs[0].key;
  const [activeTab, setActiveTab] = useState(initialTab);
  const { item } = useCheckIn({ id });

  const detailItems = buildDetailItems(item);
  const statusLabel = item?.checkInStatus || fallbackStatus;
  const recordCode = item?.checkInCode || fallbackCode;

  const ActivePage =
    tabs.find((tab) => tab.key === activeTab)?.component ?? OverviewPage;
  const editSection = editSectionByTab[activeTab] ?? editSectionByTab.overview;
  const editPath = id
    ? `/check-in-start?id=${id}#${editSection}`
    : `/check-in-start#${editSection}`;

  return (
    <div style={shellStyle}>
      <div
        className="d-flex flex-column flex-md-row align-items-md-start justify-content-between gap-3"
        style={topBarStyle}
      >
        <div>
          <h4
            className="mb-2"
            style={{ color: pageText, fontSize: 18, fontWeight: 700 }}
          >
            Check-In Details
          </h4>
          <div style={{ color: pageText, fontSize: 15 }}>
            <Link to="/dashboards" style={{ color: pageText }}>Dashboard</Link> &gt;{' '}
            <Link to="/check-in-dashboard" style={{ color: pageText }}>Check-in</Link> &gt; Check-In Details
          </div>
        </div>

        <div className="d-flex flex-wrap gap-2">
          <Button
            as={Link}
            to="/check-in-list"
            variant="outline-primary"
            className="edit-detail-btn-cancel d-inline-flex align-items-center justify-content-center gap-2 px-4"
            style={outlineButtonStyle}
          >
            <IconifyIcon icon="ri:arrow-left-s-line" width={18} height={18} />
            <span>Back</span>
          </Button>
          <Button as={Link} to={editPath} style={primaryButtonStyle}>
            Edit Details
          </Button>
        </div>
      </div>

      <div style={{ padding: "30px 24px" }}>
        <div
          className="mb-4"
          style={{ ...cardStyle, padding: "25px 29px 22px" }}
        >
          <div className="d-flex align-items-center gap-4 mb-3">
            <span
              style={{
                background: "#e6fbea",
                borderRadius: 8,
                color: "#21865f",
                display: "inline-block",
                fontSize: 16,
                fontWeight: 700,
                padding: "8px 16px",
              }}
            >
              {statusLabel}
            </span>
            <span style={{ color: pageText, fontSize: 17, fontWeight: 700 }}>
              {recordCode}
            </span>
          </div>

          <div
            style={{
              display: "grid",
              gap: 20,
              gridTemplateColumns: "repeat(8, minmax(120px, 1fr))",
              overflowX: "auto",
            }}
          >
            {detailItems.map((item) => (
              <div key={item.label} style={{ minWidth: 120 }}>
                <p className="mb-2" style={{ color: pageText, fontSize: 15 }}>
                  {item.label}
                </p>
                <p
                  className="mb-0"
                  style={{ color: pageText, fontSize: 16, fontWeight: 700 }}
                >
                  {item.value}
                </p>
              </div>
            ))}
          </div>
        </div>

        <div className="mb-4" style={{ ...cardStyle, padding: "8px 10px" }}>
          <div
            style={{
              display: "flex",
              flexWrap: "wrap",
              gap: 3,
              width: "100%",
              justifyContent: "space-between",
            }}
          >
            {tabs.map((tab) => {
              const isActive = activeTab === tab.key;

              return (
                <Button
                  key={tab.key}
                  type="button"
                  variant="light"
                  onClick={() => setActiveTab(tab.key)}
                  className="d-inline-flex align-items-center justify-content-center gap-2"
                  style={{
                    background: isActive ? "#f3f8fb" : "#fff",
                    border: isActive
                      ? "1px solid #c7d2dc"
                      : "1px solid #edf0f4",
                    borderRadius: 8,
                    color: pageText,
                    fontSize: 15,
                    fontWeight: 700,
                    height: 45,
                    padding: "0 16px",
                    whiteSpace: "nowrap",
                  }}
                >
                  {tab.iconCircle ? (
                    <span style={{
                      background: tab.iconCircle,
                      borderRadius: "50%",
                      display: "inline-flex",
                      alignItems: "center",
                      justifyContent: "center",
                      width: 28,
                      height: 28,
                      flexShrink: 0,
                    }}>
                      <IconifyIcon icon={tab.icon} color={tab.iconColor} width={18} height={18} />
                    </span>
                  ) : tab.iconSvg ? (
                    tab.iconSvg
                  ) : tab.iconBgRound ? (
                    <span style={{
                      background: tab.iconBgRound,
                      borderRadius: 10,
                      display: "inline-flex",
                      alignItems: "center",
                      justifyContent: "center",
                      padding: 4,
                      flexShrink: 0,
                    }}>
                      <IconifyIcon icon={tab.icon} color={tab.iconColor} width={tab.iconSize ?? 24} height={tab.iconSize ?? 24} />
                    </span>
                  ) : (
                    <IconifyIcon icon={tab.icon} color={tab.iconColor} width={tab.iconSize ?? 24} height={tab.iconSize ?? 24} />
                  )}
                  <span>{tab.label}</span>
                </Button>
              );
            })}
          </div>
        </div>

        <div style={{ ...cardStyle, minHeight: 290 }}>
          <ActivePage record={item} />
        </div>
      </div>
    </div>
  );
};

export default CheckInDetailsPage;


